# Disable IPv6 on All Network Adapters Write-Host "Disabling IPv6 on all network adapters..." -ForegroundColor Cyan # Disable IPv6 via registry (global) Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip6\Parameters" -Name "DisabledComponents" -Value 0xFF -Type DWord -Force -ErrorAction Stop # Disable IPv6 on each adapter $adapters = Get-NetAdapter | Where-Object { $_.Status -eq "Up" } foreach ($adapter in $adapters) { Disable-NetAdapterBinding -Name $adapter.Name -ComponentID ms_tcpip6 -ErrorAction SilentlyContinue Write-Host " Disabled IPv6 on: $($adapter.Name)" -ForegroundColor Gray } Write-Host "IPv6 has been disabled on all network adapters." -ForegroundColor Green Write-Host "A reboot is required for the global setting to take effect." -ForegroundColor Yellow